use std::fs

fn digit_val(c: char) -> int {
    let b = c as int
    if b >= 48 && b <= 57 { b - 48 } else if b >= 65 && b <= 90 { b - 55 } else { b - 87 }
}

fn digit_char(d: int) -> string {
    let digits = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    let cs: Vec<char> = digits.chars().collect()
    let c = cs[d]
    "${c}"
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().collect()
        if parts.len() < 3 {
            continue
        }
        let from = parts[1].parse::<int>().unwrap_or(10)
        let to = parts[2].parse::<int>().unwrap_or(10)
        let mut n: int = 0
        for c in parts[0].chars() {
            n = n * from + digit_val(c)
        }
        if n == 0 {
            println("0")
            continue
        }
        let mut out: Vec<string> = []
        while n > 0 {
            out.push(digit_char(n % to))
            n = n / to
        }
        out.reverse()
        println(out.join(""))
    }
}

